declare_lint_rule! {
    /// Enforce passing a type argument to `Array#reduce` and `Array#reduceRight` instead of
    /// asserting the type of the initial value.
    ///
    /// When the initial value of an array reduction uses a type assertion, TypeScript is unable
    /// to check that the reducer callback returns a value that is compatible with that type.
    /// By passing the type as a type parameter on the call instead, the return type of the
    /// callback is checked against the expected type.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduce((acc, n) => [...acc, n], [] as number[]);
    /// ```
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduceRight((acc, n) => [...acc, n], <number[]>[]);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```ts
    /// [1, 2, 3].reduce<number[]>((acc, n) => [...acc, n], []);
    /// ```
    ///
    /// ```ts
    /// [1, 2, 3].reduce((acc, n) => [...acc, n], []);
    /// ```
    ///
    pub UseReduceTypeParameter {
        version: "next",
        name: "useReduceTypeParameter",
        language: "ts",
        recommended: false,
        fix_kind: FixKind::Unsafe,
    }
}

pub struct RuleState {
    /// `true` when the call is `reduceRight`, `false` when it is `reduce`.
    is_reduce_right: bool,
    /// The initial value argument of the reduction (the second argument).
    initial_value: AnyJsCallArgument,
    /// The type assertion used on the initial value.
    assertion: AnyTsTypeAssertion,
}

impl Rule for UseReduceTypeParameter {
    type Query = Ast<JsCallExpression>;
    type State = RuleState;
    type Signals = Option<Self::State>;
    type Options = UseReduceTypeParameterOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();

        let member =
            AnyJsMemberExpression::cast(call.callee().ok()?.omit_parentheses().into_syntax())?;
        let is_reduce_right = match member.member_name()?.text() {
            "reduce" => false,
            "reduceRight" => true,
            _ => return None,
        };

        // The initial value is the second argument of the call.
        let [_, Some(initial_value)] = call.arguments().ok()?.get_arguments_by_index([0, 1]) else {
            return None;
        };

        let expression = initial_value.as_any_js_expression()?;
        let assertion =
            AnyTsTypeAssertion::cast(expression.clone().omit_parentheses().into_syntax())?;

        Some(RuleState {
            is_reduce_right,
            initial_value,
            assertion,
        })
    }

    fn diagnostic(_: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let method = if state.is_reduce_right {
            "Array#reduceRight"
        } else {
            "Array#reduce"
        };

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.initial_value.range(),
                markup! {
                    "The initial value of "{method}" uses a type assertion."
                },
            )
            .note(markup! {
                "Type assertions can hide type mismatches in the reducer callback. Use a type parameter on the call instead, so TypeScript checks the return type."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<JsRuleAction> {
        let call = ctx.query();
        let inner_value = state.assertion.expression().ok()?;
        let mut mutation = ctx.root().begin();

        let message = if call.type_arguments().is_none() {
            // Move the asserted type to a type parameter on the call and remove
            // the assertion from the initial value.
            let asserted_type = state
                .assertion
                .ty()
                .ok()?
                .with_leading_trivia_pieces([])?
                .with_trailing_trivia_pieces([])?;

            // Preserve the leading trivia (e.g. the space after the comma) of the
            // original initial value on the unwrapped expression.
            let leading = state.initial_value.syntax().first_token()?.leading_trivia();
            let new_expression = inner_value.with_leading_trivia_pieces(leading.pieces())?;

            let args = call.arguments().ok()?;
            let mut items = Vec::new();
            let mut separators: Vec<JsSyntaxToken> = Vec::new();
            for element in args.args().elements() {
                let node = element.node.ok()?;
                if node.range() == state.initial_value.range() {
                    items.push(AnyJsCallArgument::AnyJsExpression(new_expression.clone()));
                } else {
                    items.push(node);
                }
                if let Some(separator) = element.trailing_separator.ok()? {
                    separators.push(separator);
                }
            }
            let new_args = args.with_args(make::js_call_argument_list(items, separators));

            let type_arguments = make::ts_type_arguments(
                make::token(T![<]),
                make::ts_type_argument_list([asserted_type], []),
                make::token(T![>]),
            );

            let new_call = call
                .clone()
                .with_arguments(new_args)
